#include "terrain_contour_lod.h"
#include "outline_ids.h"
#include <cmath>
#include <iostream>
#include <set>
#include <stdexcept>
using namespace game;
void require(bool v,const char* m){if(!v)throw std::runtime_error(m);}
terrain_mesh_data ring(){terrain_mesh_data m;const int n=320;auto tri=[&](std::array<float,3>a,std::array<float,3>b,std::array<float,3>c,std::array<float,3>normal,int id){for(auto p:{a,b,c}){m.indices.push_back(uint16_t(m.vertices.size()));terrain_vertex v(p,normal,{{255,255,255,255}});v.editor_palette={{0,0}};v.outline_id=outline_terrace_id(id);m.vertices.push_back(v);}};for(int i=0;i<n;++i){float a=i*6.283185307f/n,b=((i+1)%n)*6.283185307f/n;std::array<float,3>at={{10*std::cos(a),4,10*std::sin(a)}},bt={{10*std::cos(b),4,10*std::sin(b)}},ab=at,bb=bt;ab[1]=bb[1]=2;tri(at,{{0,4,0}},bt,{{0,1,0}},3);tri(at,bt,ab,{{std::cos(a),0,std::sin(a)}},3);tri(bt,bb,ab,{{std::cos(a),0,std::sin(a)}},3);}return m;}
void check_morph(const std::vector<TerrainLodVariant>& levels){
 for(const auto& level:levels)for(int step=0;step<=20;++step){double t=step/20.;
  for(size_t i=0;i<level.mesh.indices.size();i+=3){std::array<double,2> p[3];
   for(int j=0;j<3;++j){auto k=level.mesh.indices[i+j];const auto& v=level.mesh.vertices[k];p[j]={{v.position[0]+t*level.morph_delta_xz[k][0],v.position[2]+t*level.morph_delta_xz[k][1]}};}
   if(level.mesh.vertices[level.mesh.indices[i]].normal[1]>.99f){double area=(p[1][0]-p[0][0])*(p[2][1]-p[0][1])-(p[1][1]-p[0][1])*(p[2][0]-p[0][0]);require(area<=1e-5,"intermediate morph flipped top triangle");}
  }
 }
}
terrain_mesh_data annulus(){auto mesh=ring();const size_t n=320;
 for(size_t i=0;i<n;++i){auto& center=mesh.vertices[mesh.indices[i*9+1]];const auto& a=mesh.vertices[mesh.indices[i*9]].position;center.position={{a[0]*.45f,4,a[2]*.45f}};}
 // Leave a protected interior opening; the original fan is replaced by quads.
 terrain_mesh_data out;auto tri=[&](terrain_vertex a,terrain_vertex b,terrain_vertex c){for(auto v:{a,b,c}){out.indices.push_back(uint16_t(out.vertices.size()));out.vertices.push_back(v);}};
 for(size_t i=0;i<n;++i){auto a=mesh.vertices[mesh.indices[i*9]],b=mesh.vertices[mesh.indices[i*9+2]],ia=a,ib=b;ia.position[0]*=.45f;ia.position[2]*=.45f;ib.position[0]*=.45f;ib.position[2]*=.45f;tri(a,ia,b);tri(b,ia,ib);for(int k=3;k<9;k+=3)tri(mesh.vertices[mesh.indices[i*9+k]],mesh.vertices[mesh.indices[i*9+k+1]],mesh.vertices[mesh.indices[i*9+k+2]]);}
 return out;
}
terrain_mesh_data touching_hole(){terrain_mesh_data out;const std::vector<std::vector<std::array<float,2>>> loops={{{{-1,0}},{{0,1}},{{1,0}},{{1,-2}},{{-1,-2}}},{{{0,0}},{{-.2f,-1}},{{.2f,-1}}}};int id=1;for(const auto& loop:loops){for(size_t i=0;i<loop.size();++i){auto a=loop[i],b=loop[(i+1)%loop.size()];for(auto p:std::vector<std::array<float,3>>{{{a[0],4,a[1]}},{{b[0],4,b[1]}},{{a[0],2,a[1]}},{{b[0],4,b[1]}},{{b[0],2,b[1]}},{{a[0],2,a[1]}}}){terrain_vertex v(p,{{1,0,0}},{{255,255,255,255}});v.editor_palette={{0,0}};v.outline_id=outline_terrace_id(id);out.indices.push_back(uint16_t(out.vertices.size()));out.vertices.push_back(v);}}++id;}
 const std::array<float,2> a={{-1,0}},v={{0,1}},b={{1,0}},c={{1,-2}},d={{-1,-2}},q={{0,0}},r={{-.2f,-1}},t={{.2f,-1}};
 for(auto tri:std::vector<std::array<std::array<float,2>,3>>{{{a,v,q}},{{v,b,q}},{{a,q,r}},{{a,r,d}},{{d,r,t}},{{d,t,c}},{{c,t,b}},{{b,t,q}}})for(auto p:tri){terrain_vertex vertex({{p[0],4,p[1]}},{{0,1,0}},{{255,255,255,255}});vertex.editor_palette={{0,0}};vertex.outline_id=outline_terrace_id(1);out.indices.push_back(uint16_t(out.vertices.size()));out.vertices.push_back(vertex);}
 return out;}
int main(){try{const std::array<std::array<float,2>,3> start={{{{0,0}},{{1,0}},{{0,-1}}}},end={{{{0,0}},{{-2,0}},{{0,.5f}}}};require(!terrain_morph_triangle_valid(start,end),"simultaneous morph inversion between valid endpoints accepted");require(terrain_morph_triangle_valid(start,start),"static triangle rejected");auto source=ring();TerrainLodSettings s;auto exact=build_terrain_contour_lods(source,s,{});require(exact.size()==5,"configured level count");for(auto& v:exact)require(v.actual_percent==0&&v.world_error==0,"zero percent must stay exact");s.set_contour_percent(50);auto variants=build_terrain_contour_lods(source,s,{});require(variants[0].actual_percent==0,"nearest contour changed");for(int i=0;i<5;++i){auto& v=variants[i];require(v.requested_percent==12.5f*i,"fraction not linear from nearest");require(v.actual_percent<=v.requested_percent+.001f,"too much contour reduction");require(v.morph_delta_xz.size()==v.mesh.vertices.size(),"morph array size");for(auto& p:v.mesh.vertices)require(p.position[1]==2||p.position[1]==4,"height changed");}check_morph(variants);auto targets=build_terrain_contour_debug(variants.back(),4,.2f);require(targets.mesh.indices.size()>variants.back().mesh.indices.size(),"collapse targets overlay missing");auto points=build_terrain_contour_debug(variants.back(),5,.2f);require(points.mesh.indices.size()>variants.back().mesh.indices.size(),"active contour markers missing");require(variants.back().mesh.vertices.size()<variants.front().mesh.vertices.size(),"coarse variants keep unused full vertex copies");require(!variants.back().collapses.empty(),"progressive collapse dependencies not recorded");TerrainContourConstraints contact;contact.bounds={{-1,-2,1,100}};contact.protected_disks={{{-.2f,-1,.001f,0}},{{.2f,-1,.001f,0}}};auto contact_lods=build_terrain_contour_lods(touching_hole(),s,contact);require(contact_lods.back().actual_percent==0,"contour collapse touched a hole vertex");auto sharp=ring();for(auto& v:sharp.vertices)if(v.position[0]>9.99f&&std::abs(v.position[2])<.001f)v.position[0]=12;auto sharp_lods=build_terrain_contour_lods(sharp,s,{});bool kept=false;for(auto index:sharp_lods.back().mesh.indices)kept|=sharp_lods.back().mesh.vertices[index].position[0]>11.99f;require(kept,"sharp silhouette removed before low-curvature points");check_morph(sharp_lods);auto hole=annulus();auto hole_lods=build_terrain_contour_lods(hole,s,{});check_morph(hole_lods);for(const auto& level:hole_lods)for(auto index:level.mesh.indices){const auto& p=level.mesh.vertices[index].position;require(p[0]*p[0]+p[2]*p[2]>=20.24f,"LOD filled the interior opening");}require(variants.back().actual_percent>45,"unconstrained circle must approach 50 percent");require(variants.back().mesh.indices.size()<source.indices.size(),"coarse mesh did not drop triangles");TerrainContourConstraints c;c.protected_disks.push_back({{0,0,20,0}});auto protected_lods=build_terrain_contour_lods(source,s,c);require(protected_lods.back().actual_percent==0,"protected footprint changed");s.set_contour_percent(90);auto aggressive=build_terrain_contour_lods(source,s,{});check_morph(aggressive);require(aggressive.back().actual_percent>85,"independent-set cap prevents progressive far reduction");s.set_lod_count(1);auto single=build_terrain_contour_lods(source,s,{});require(single.size()==1&&single[0].actual_percent==0,"single level simplified");std::cout<<"Contour LOD CPU checks passed: 5 levels, 0..50%, exact nearest, pinned footprint, fixed heights and morph arrays\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
